class Solution:
    def rangeSumBST(self, root: 'TreeNode | None', low: int, high: int) -> int:
        if not root:
            return 0
        if root.val < low:
            return self.rangeSumBST(root.right, low, high)    # left subtree is even smaller: skip it
        if root.val > high:
            return self.rangeSumBST(root.left, low, high)     # right subtree is even larger: skip it
        return (root.val                                       # in range: count it and search both sides
                + self.rangeSumBST(root.left, low, high)
                + self.rangeSumBST(root.right, low, high))
